import asyncio
from typing import Any, Callable, Dict, List, Optional


class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency < 1:
            raise ValueError("concurrency must be at least 1")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be >= 0")

        self.concurrency: int = concurrency
        self.max_queue_size: int = max_queue_size

        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: List[asyncio.Task] = []
        self._is_started: bool = False
        self._is_shutting_down: bool = False
        self._counter: int = 0
        self._active_tasks: Dict[asyncio.Task, asyncio.Future] = {}

    async def start(self) -> None:
        """Spawns the pool worker tasks if not already running."""
        if self._is_started:
            return
        self._is_started = True
        self._workers = [
            asyncio.create_task(self._worker(), name=f"AsyncWorkerPool-worker-{i}")
            for i in range(self.concurrency)
        ]

    async def submit(
        self,
        coro_func: Callable[..., Any],
        *args: Any,
        priority: int = 0,
    ) -> asyncio.Future:
        """
        Enqueues a coroutine function coro_func(*args) to be executed by pool workers.
        Higher priority integers execute before lower priority integers.
        Returns an asyncio.Future resolving with result or exception.
        """
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        future: asyncio.Future = loop.create_future()

        self._counter += 1
        # asyncio.PriorityQueue pops lowest value first.
        # Use -priority so higher priority integers are popped first.
        # self._counter serves as a tiebreaker for equal priorities (FIFO).
        item = (-priority, self._counter, coro_func, args, future)

        await self._queue.put(item)
        return future

    async def _worker(self) -> None:
        """Worker task loop processing items from the priority queue."""
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            _, _, coro_func, args, future = item

            if future.done():
                self._queue.task_done()
                continue

            current_task = asyncio.current_task()
            if current_task is not None:
                self._active_tasks[current_task] = future

            try:
                res = await coro_func(*args)
                if not future.done():
                    future.set_result(res)
            except asyncio.CancelledError:
                if not future.done():
                    future.cancel()
                raise
            except (Exception, BaseException) as exc:
                if not future.done():
                    future.set_exception(exc)
                if isinstance(exc, (KeyboardInterrupt, SystemExit)):
                    raise
            finally:
                if current_task is not None:
                    self._active_tasks.pop(current_task, None)
                self._queue.task_done()

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        """
        Shuts down the worker pool.
        - If drain=True: waits for queued tasks to complete before stopping workers.
        - If drain=False: cancels all queued and executing tasks immediately.
        - Respects optional timeout in seconds.
        """
        self._is_shutting_down = True

        async def _do_shutdown() -> None:
            if drain:
                # Wait for all enqueued work to be marked as task_done()
                await self._queue.join()
                for worker in self._workers:
                    worker.cancel()
                if self._workers:
                    await asyncio.gather(*self._workers, return_exceptions=True)
            else:
                # Cancel all waiting items in the queue
                while not self._queue.empty():
                    try:
                        item = self._queue.get_nowait()
                        self._queue.task_done()
                        _, _, _, _, future = item
                        if not future.done():
                            future.cancel()
                    except asyncio.QueueEmpty:
                        break

                # Cancel active worker tasks (which in turn cancels current work)
                for worker in self._workers:
                    worker.cancel()
                if self._workers:
                    await asyncio.gather(*self._workers, return_exceptions=True)

        try:
            if timeout is not None:
                await asyncio.wait_for(_do_shutdown(), timeout=timeout)
            else:
                await _do_shutdown()
        except asyncio.TimeoutError:
            # Force cancel remaining queued items and worker tasks upon timeout
            while not self._queue.empty():
                try:
                    item = self._queue.get_nowait()
                    self._queue.task_done()
                    _, _, _, _, future = item
                    if not future.done():
                        future.cancel()
                except asyncio.QueueEmpty:
                    break

            for worker in self._workers:
                worker.cancel()
            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)
        finally:
            self._workers.clear()
            self._is_started = False
